def authenticate_request(request):
    token = request.headers.get("Authorization", "").removeprefix("Bearer ")
    if not token:
        raise AuthError("missing credential")
    try:
        claims = verify_jwt(token, public_key=SERVER_PUBLIC_KEY)
    except InvalidSignatureError:
        raise AuthError("invalid credential")
    except ExpiredTokenError:
        raise AuthError("credential expired")
    return Identity(subject=claims["sub"], client_id=claims.get("client_id"))

def verify_token(token):
    if not token or not token_store.is_valid(token):
        raise AuthError("invalid or missing token")
    return token_store.get_identity(token)

def handle_request(request):
    identity = authenticate_request(request)   # always first, no exceptions
    check_authorization(identity, request.method)
    return dispatch(request, identity)

def handle_request(request):
    identity = authenticate(request)   # first, always
    return route_to_handler(request, identity)

def handle_request(request):
    try:
        identity = authenticate_request(request)
    except AuthError as e:
        log_auth_event(success=False, reason=str(e), source=request.remote_addr)
        return error_response(401, "authentication failed")
    log_auth_event(success=True, subject=identity.subject, source=request.remote_addr)
    return dispatch(request, identity)
